import { Quaternion, Vector3 } from 'three';
import type { DevicePartConfig } from '../../config/schema';

/**
 * 两阶段爆炸动画数学（见 docs/project/EXPLOSION-PLANNING.md §四）。
 *
 * 每个部件在自己 `sequence` 窗口内分两段：
 *   前 REMOVAL_PHASE：A 阶段 —— 沿推导出的拆除方向"起吊"到安全距离；
 *   后 1-REMOVAL_PHASE：B 阶段 —— 从起吊位过渡到装箱格位。
 * A 只给碰撞安全的小位移，大幅铺开交给 B 的装箱，因此 A 终点即 B 起点，无缝衔接。
 */

/** 部件自身窗口里前多少比例用于 A 起吊。 */
export const REMOVAL_PHASE = 0.55;

function smoothstep(value: number) {
  const clamped = Math.min(1, Math.max(0, value));
  return clamped * clamped * (3 - 2 * clamped);
}

function normalizeDirection(direction: [number, number, number]) {
  const vector = new Vector3(...direction);
  return vector.lengthSq() > 0 ? vector.normalize() : null;
}

/** 部件窗口内归一化进度（0..1）。 */
function localProgress(sequence: [number, number], progress: number) {
  const [start, end] = sequence;
  const clamped = Math.min(1, Math.max(0, progress));
  if (end === start) return Number(clamped >= end);
  return Math.min(1, Math.max(0, (clamped - start) / (end - start)));
}

/**
 * 把世界坐标方向换算成挂点局部坐标方向。
 *
 * FBX 导入的模型里，部件挂点通常带 −90° 的 X 预旋转；`direction/distance` 是
 * 世界坐标下的拆除方向，直接加到 `object.position`（局部坐标）上会被父级旋转
 * 再旋转一次，导致部件沿错误轴向移动。这里按挂点世界旋转求逆做换算。
 */
export function localDirection(direction: Vector3, rotation: Quaternion | null) {
  return rotation ? direction.clone().applyQuaternion(rotation.clone().invert()) : direction.clone();
}

export interface ExplodedPositionOptions {
  /**
   * B 阶段目标：部件**局部**坐标偏移量（= 格心 − 部件中心，已换算到局部）。
   * 缺省时退化为旧的单阶段行为（只做 A 起吊）。
   */
  layoutOffset?: Vector3 | null;
  /** 挂点世界旋转，用于把世界方向换算到局部；缺省视为无旋转。 */
  rotation?: Quaternion | null;
}

/**
 * 计算某进度下的位置（只读入参，不修改任何入参，可反复调用）。
 */
export function calculateExplodedPosition(
  origin: Vector3,
  part: DevicePartConfig,
  progress: number,
  options: ExplodedPositionOptions = {},
) {
  const local = localProgress(part.sequence, progress);
  const layoutOffset = options.layoutOffset ?? null;
  const atOrigin = () => origin.clone();
  if (local <= 0) return atOrigin();

  const direction = normalizeDirection(part.direction);
  const terminal = layoutOffset ? origin.clone().add(layoutOffset) : null;
  if (!direction || part.distance <= 0) {
    // 没有拆除方向的部件只在 B 阶段入驻格子。
    if (!terminal) return atOrigin();
    return atOrigin().lerp(terminal, smoothstep(local));
  }

  const worldDirection = localDirection(direction, options.rotation ?? null);
  const removed = origin.clone().addScaledVector(worldDirection, part.distance);
  if (!terminal) return origin.clone().lerp(removed, smoothstep(local));

  if (local <= REMOVAL_PHASE) {
    return origin.clone().lerp(removed, smoothstep(local / REMOVAL_PHASE));
  }
  const settle = smoothstep((local - REMOVAL_PHASE) / (1 - REMOVAL_PHASE));
  return removed.clone().lerp(terminal, settle);
}

/** 爆炸终态位置（progress = 1）。便于计算终态包围盒与做单测断言。 */
export function explodedTerminalPosition(
  origin: Vector3,
  part: DevicePartConfig,
  options: ExplodedPositionOptions = {},
) {
  return calculateExplodedPosition(origin, part, 1, options);
}

export function isPartIncluded(part: DevicePartConfig, selectedLevel: number) {
  return part.level <= selectedLevel;
}
