import { Box3, MathUtils, Vector3 } from 'three';
import type { DeviceView } from './useDeviceView';

export interface ViewportRect {
  left: number;
  right: number;
  top: number;
  bottom: number;
}

export function getViewDirection(view: DeviceView) {
  if (view === 'front') return new Vector3(0, 0, 1);
  if (view === 'back') return new Vector3(0, 0, -1);
  if (view === 'side') return new Vector3(1, 0, 0);
  return new Vector3(0.35, 0.08, 1).normalize();
}

export function getAvailableViewport({ width, height, detailsOpen }: { width: number; height: number; detailsOpen: boolean }): ViewportRect {
  if (!detailsOpen) return { left: 20, right: width - 20, top: 110, bottom: height - 150 };
  if (width < 768 && height > 600) {
    return { left: 20, right: width - 20, top: 150, bottom: Math.round(height * 0.58) - 36 };
  }
  if (height <= 600) {
    return { left: 20, right: Math.max(170, width - 320), top: 80, bottom: height - 112 };
  }
  return { left: width > 1100 ? 285 : 25, right: width - 370, top: 110, bottom: height - 178 };
}

export function calculateFitDistance(size: Vector3, viewport: ViewportRect, fovDegrees: number, cameraAspect: number) {
  const availableWidth = Math.max(40, viewport.right - viewport.left);
  const availableHeight = Math.max(40, viewport.bottom - viewport.top);
  const verticalFov = MathUtils.degToRad(fovDegrees);
  const viewportAspect = availableWidth / availableHeight;
  const effectiveAspect = Math.max(0.01, Math.min(cameraAspect, viewportAspect));
  const heightDistance = size.y / (2 * Math.tan(verticalFov / 2));
  const widthDistance = size.x / (2 * Math.tan(verticalFov / 2) * effectiveAspect);
  return Math.max(heightDistance, widthDistance, size.z) * 1.3;
}

export interface FitDistanceOptions {
  /** 画布尺寸（CSS px）。给了它才能把取景限制在"UI 没盖住"的可用区里。 */
  canvas?: { width: number; height: number };
  /**
   * 是否把取景限制在可用区（`viewport` 去掉上下浮层占位后的那块）内。
   * 展开态必须为 true：部件会铺到四边，不缩进的话最外沿会钻到标题/拆解坞底下（实测贴边）。
   */
  respectOverlays?: boolean;
  /** 额外余量，缺省 1.25。 */
  margin?: number;
}

/**
 * 按包围盒在**相机坐标系**里的投影范围算取景距离。
 *
 * `calculateFitDistance` 只用了 size.x / size.y，等于假设"正对着看"；一旦是 3/4 视角，
 * 投影宽度会长到对角线长度，包围盒的角就出画了——拆解终态铺得越开越明显（塔式设备的
 * 十级塔节拉开后，整塔 + 吊到旁边的框架能铺到 40 m 见方，按老公式四角必然被切）。
 * 这里把 8 个角投到相机的右/上轴取极值，既不出画，也不像"按包围球"那样把正视图也拉远。
 */
export function calculateFitDistanceForBounds(
  bounds: Box3,
  viewDirection: Vector3,
  viewport: ViewportRect,
  fovDegrees: number,
  cameraAspect: number,
  options: FitDistanceOptions = {},
) {
  const { canvas, respectOverlays = false, margin = 1.25 } = options;
  // 缩进到可用区本身已经留了余量（上下浮层占掉约三成高度），再乘 1.25 会双重留白、模型过小。
  const effectiveMargin = respectOverlays ? Math.min(margin, 1.05) : margin;
  const availableWidth = Math.max(40, viewport.right - viewport.left);
  const availableHeight = Math.max(40, viewport.bottom - viewport.top);
  const viewportAspect = availableWidth / availableHeight;
  let tanVertical = Math.tan(MathUtils.degToRad(fovDegrees) / 2);
  let tanHorizontal = tanVertical * Math.max(0.01, Math.min(cameraAspect, viewportAspect));
  if (respectOverlays && canvas && canvas.width > 0 && canvas.height > 0) {
    // 可用区占整幅的比例：等价于把半视角按同样比例收窄，取景就落在 UI 之外。
    tanVertical *= Math.min(1, availableHeight / canvas.height);
    tanHorizontal *= Math.min(1, availableWidth / canvas.width);
  }

  const forward = viewDirection.clone().normalize().negate();
  const right = new Vector3().crossVectors(new Vector3(0, 1, 0), forward);
  if (right.lengthSq() < 1e-8) right.set(1, 0, 0);
  right.normalize();
  const up = new Vector3().crossVectors(forward, right).normalize();

  const center = bounds.getCenter(new Vector3());
  const corner = new Vector3();
  let maxRight = 0;
  let maxUp = 0;
  let maxDepth = 0;
  for (let index = 0; index < 8; index += 1) {
    corner
      .set(
        index & 1 ? bounds.max.x : bounds.min.x,
        index & 2 ? bounds.max.y : bounds.min.y,
        index & 4 ? bounds.max.z : bounds.min.z,
      )
      .sub(center);
    maxRight = Math.max(maxRight, Math.abs(corner.dot(right)));
    maxUp = Math.max(maxUp, Math.abs(corner.dot(up)));
    maxDepth = Math.max(maxDepth, Math.abs(corner.dot(forward)));
  }
  return Math.max(maxRight / Math.max(1e-6, tanHorizontal), maxUp / Math.max(1e-6, tanVertical), maxDepth * 0.6) * effectiveMargin;
}
